    /// e.g. when the element is destroyed or when RemoveEventListener() is called with the same parameters passed here.<br/>
    /// </summary>
    /// <remarks>C++: <c>void Rml::Element::AddEventListener(EventId id, EventListener* listener, bool in_capture_phase = false)</c></remarks>
